<template>
  <section ref="root" class="client-settings" aria-label="客户端设置">
    <nav class="settings-nav" aria-label="客户端设置"><div class="tabs" role="tablist" aria-label="客户端设置分类"><button v-for="item in tabs" :id="`client-tab-${item.key}`" :key="item.key" type="button" role="tab" :aria-selected="tab===item.key" :tabindex="tab===item.key?0:-1" @keydown="tabKey($event,item.key)" :aria-controls="`client-${item.key}`" @click="changeTab(item.key)">{{ item.label }}</button></div></nav><div class="settings-main"><header><div><small>YOUR DESKTOP, YOUR RHYTHM</small><h1>{{tab==='lyrics'?'桌面歌词':'快捷轮盘'}}</h1><p>{{tab==='lyrics'?'留一行歌词，陪你做自己的事。':'让常用操作，随手可达。'}}</p></div><button type="button" :disabled="editor.busy||editor.dirty" @click="load">重新读取</button></header>

    <p v-if="editor.error||readError" role="alert" class="error">{{ editor.error||readError }}</p>
    <p v-if="!draft">{{ loading?'正在读取本机设置…':'无法读取本机设置，请重试。' }}</p>
    <template v-if="draft"><fieldset>
      <section v-show="tab==='lyrics'" id="client-lyrics" role="tabpanel" aria-labelledby="client-tab-lyrics">
        <div class="preview" :style="previewStyle"><small>透明桌面歌词 · 外观预览</small><div class="sample">让晚风，慢一点</div><div v-if="draft.lyricsStyle?.rows===2" class="sample-next">把时间留在山海之间</div></div>
        <label class="row"><span>显示桌面歌词<small>也可从轮盘与播放器开启</small></span><input v-model="draft.lyricsVisible" type="checkbox" role="switch" aria-label="显示桌面歌词"></label>
        <label class="row"><span>锁定浮窗<small>防止误拖动，可在这里解锁</small></span><input v-model="draft.lyricsLocked" type="checkbox" role="switch" aria-label="锁定浮窗"></label>
        <div v-if="draft.lyricsStyle" class="group">
          <div class="two"><label>字体<AppSelect v-model="draft.lyricsStyle.fontFamily" aria-label="歌词字体"><option value="system">系统默认</option><option value="sans">微软雅黑</option><option value="serif">宋体</option></AppSelect></label><label>歌词行数<AppSelect v-model.number="draft.lyricsStyle.rows" aria-label="歌词行数"><option :value="2">双行 · 当前与下一句</option><option :value="1">单行 · 仅当前句</option></AppSelect></label></div>
          <label class="slider">字号<output>{{ draft.lyricsStyle.fontSize }} px</output><input v-model.number="draft.lyricsStyle.fontSize" type="range" min="22" max="48" aria-label="歌词字号"></label>
          <LyricColorPicker v-model="draft.lyricsStyle.highlight" label="歌词高亮" />
          <LyricColorPicker :model-value="draft.lyricsStyle.base||'#aab7a3'" label="歌词原色" @update:model-value="draft.lyricsStyle.base=$event" />
          <label class="row"><span>平滑上滑换句<small>跳进度时直接定位</small></span><input v-model="draft.lyricsStyle.smoothScroll" type="checkbox" role="switch" aria-label="平滑上滑换句"></label>
          <label class="slider">歌词不透明度<output>{{ Math.round((draft.lyricsStyle.opacity??.85)*100) }}%</output><input v-model.number="draft.lyricsStyle.opacity" type="range" min="0" max="1" step=".01" aria-label="歌词不透明度"></label>
        </div><button type="button" @click="recoverLyrics">找回歌词位置</button>
      </section>
      <section v-show="tab==='wheel'" id="client-wheel" role="tabpanel" aria-labelledby="client-tab-wheel"><template v-if="draft.wheel">
        <label class="row"><span>启用全局快捷轮盘<small>按住组合键，移向操作，松开执行</small></span><input v-model="draft.wheel.enabled" type="checkbox" role="switch" aria-label="启用全局快捷轮盘"></label>
        <div class="group"><label>呼出快捷键</label><button class="record" type="button" aria-label="录制轮盘快捷键" :class="{'is-recording':recording}" @click="toggleRecord" @keydown="recordKey" @keyup="finishRecord"><span><kbd v-for="key in draft.wheel.accelerator.split('+')" :key="key">{{ key==='Control'?'Ctrl':key }}</kbd></span><small>{{ recording?'请按下组合键…':'点击录制' }}</small></button><p role="status">{{ recordMessage||'支持 Ctrl＋Alt，可加 Shift、空格、字母、数字或 F1–F12。Esc 取消录制。' }}</p></div>
        <label class="row"><span>全屏应用中也允许呼出<small>默认关闭，减少对其他应用的干扰</small></span><input v-model="draft.wheel.allowFullscreen" type="checkbox" role="switch" aria-label="全屏应用中也允许呼出"></label>
        <div class="two slots"><label v-for="(slot,index) in draft.wheel.slots" :key="index">位置 {{ index+1 }}<AppSelect :model-value="slot" :aria-label="`轮盘位置 ${index+1}`" @update:model-value="moveSlot(index,String($event))"><option v-for="command in DESKTOP_WHEEL_COMMANDS" :key="command" :value="command">{{ commandLabels[command] }}</option></AppSelect></label></div>
        <p>中心、Esc 或右键可取消。独立全局媒体快捷键已移除，播放操作保留在轮盘与播放器中。</p>
      </template></section>
    </fieldset><footer class="settings-footer"><span role="status">{{ recording?'录制结束后自动生效':editor.busy?'正在自动保存…':editor.error?'设置未保存，可重试':editor.dirty?'正在应用改动…':'修改后立即生效，自动保存' }}</span><button v-if="editor.error" type="button" :disabled="editor.busy||recording" @click="autosave.request()">重试保存</button></footer></template>
  </div></section>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {DESKTOP_WHEEL_COMMANDS,type DesktopWheelCommand} from '@studyroom/contracts';
import AppSelect from '../../components/controls/AppSelect.vue';
import LyricColorPicker from '../../components/controls/LyricColorPicker.vue';
import {DesktopSettingsDraft} from '../../audio/lyrics/desktopSettingsDraft';
import {SettingsAutosave} from '../../audio/lyrics/settingsAutosave';
import {desktopMusicState as model,saveDesktopMusic} from '../../audio/lyrics/desktopLyrics';
import {runMotion,type MotionHandle} from '../../motion/runtime';
const editor=reactive(new DesktopSettingsDraft()),draft=computed(()=>editor.draft),tab=ref('lyrics'),root=ref<HTMLElement>(),loading=ref(false),readError=ref('');
const tabs=[{key:'lyrics',label:'桌面歌词'},{key:'wheel',label:'快捷轮盘'}];
const commandLabels:Record<DesktopWheelCommand,string>={'play-pause':'播放／暂停',next:'下一首',previous:'上一首',mute:'音乐静音',focus:'专注开始／暂停',sound:'声音面板',space:'返回空间',lyrics:'桌面歌词'};
const previewStyle=computed(()=>{const s=draft.value?.lyricsStyle;return {'--lyric-size':(s?.fontSize??38)+'px','--lyric-highlight':s?.highlight||'#deefaa','--lyric-base':s?.base||'#aab7a3','--lyric-opacity':s?.opacity??.85,fontFamily:s?.fontFamily==='serif'?'SimSun,serif':s?.fontFamily==='sans'?'Microsoft YaHei,sans-serif':'inherit'};});
let alive=true,loadTicket=0,motion:MotionHandle|undefined;
watch(()=>model.state,state=>{if(state)editor.receive(state.settings);},{immediate:true});
async function load(){if(editor.busy)return;const bridge=window.studyRoomDesktop;if(!bridge?.getDesktopMusic){readError.value='客户端设置仅可在桌面客户端使用。';return;}const ticket=++loadTicket;loading.value=true;readError.value='';try{const state=await bridge.getDesktopMusic();if(alive&&ticket===loadTicket){model.state=state;editor.receive(state.settings);readError.value=state.error||'';}}catch(error){if(alive&&ticket===loadTicket)readError.value=error instanceof Error?error.message:'无法读取客户端设置。';}finally{if(alive&&ticket===loadTicket)loading.value=false;}}
async function save(){if(!editor.dirty)return true;return editor.save(async settings=>{const state=await saveDesktopMusic(settings);if(!state)throw new Error(model.error||'设置未保存，请重试。');return state.settings;});}
const autosave=new SettingsAutosave(save,()=>!recording.value);
watch(()=>JSON.stringify(draft.value),()=>{if(editor.dirty&&!recording.value)autosave.request();},{flush:'sync'});
function changeTab(value:string){cancelRecord();tab.value=value;motion?.revert();if(root.value)motion=runMotion(root.value,'client-settings-tab',tl=>{tl.fromTo(root.value!.querySelector('#client-'+value),{y:7,opacity:.5},{y:0,opacity:1,duration:.22});});}
function tabKey(event:KeyboardEvent,key:string){const index=tabs.findIndex(item=>item.key===key);const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:['ArrowRight','ArrowDown'].includes(event.key)?(index+1)%tabs.length:['ArrowLeft','ArrowUp'].includes(event.key)?(index+tabs.length-1)%tabs.length:-1;if(next<0)return;event.preventDefault();const value=tabs[next]!.key;changeTab(value);root.value?.querySelector<HTMLButtonElement>('#client-tab-'+value)?.focus();}
function moveSlot(index:number,value:string){const slots=draft.value?.wheel?.slots;if(!slots||!(DESKTOP_WHEEL_COMMANDS as readonly string[]).includes(value))return;const from=slots.indexOf(value as DesktopWheelCommand);if(from<0)return;const old=slots[index]!;slots[index]=value as DesktopWheelCommand;slots[from]=old;}
async function recoverLyrics(){readError.value='';try{await window.studyRoomDesktop?.resetDesktopLyricsPosition?.();}catch{readError.value='无法找回歌词窗口，请重试。';}}
let recordingTicket=0,recordingTimer:ReturnType<typeof setTimeout>|undefined;
const recording=ref(false),recordMessage=ref('');let originalChord='',candidate='';
function releaseRecording(){clearTimeout(recordingTimer);recordingTicket++;void window.studyRoomDesktop?.setDesktopWheelRecording?.(false).catch(()=>{});}
function cancelRecord(){releaseRecording();if(recording.value&&draft.value?.wheel)draft.value.wheel.accelerator=originalChord;recording.value=false;candidate='';}
async function toggleRecord(){if(recording.value){cancelRecord();return;}const ticket=++recordingTicket;try{await window.studyRoomDesktop?.setDesktopWheelRecording?.(true);}catch{recordMessage.value='无法暂停旧轮盘，请重试。';return;}if(!alive||ticket!==recordingTicket){releaseRecording();return;}originalChord=draft.value?.wheel?.accelerator||'';recordMessage.value='按下组合键并松开，Esc 取消。';candidate='';recording.value=true;recordingTimer=setTimeout(()=>{cancelRecord();recordMessage.value='录制超时，原快捷键未改变。';},25000);}
function recordKey(event:KeyboardEvent){if(!recording.value)return;event.preventDefault();event.stopPropagation();if(event.key==='Escape'){cancelRecord();recordMessage.value='已取消录制，原快捷键未改变。';return;}if(event.getModifierState('AltGraph')||!event.ctrlKey||!event.altKey){recordMessage.value='请使用 Ctrl＋Alt，可加 Shift 和一个支持的按键。';return;}const key=['Control','Alt','Shift'].includes(event.key)?'':event.code==='Space'?'Space':/^[a-z0-9]$/i.test(event.key)?event.key.toUpperCase():/^F([1-9]|1[0-2])$/.test(event.key)?event.key:null;if(key===null){candidate='';recordMessage.value='该按键不受支持，请重新录制。';return;}candidate=['Control','Alt',...(event.shiftKey?['Shift']:[]),...(key?[key]:[])].join('+');if(draft.value?.wheel)draft.value.wheel.accelerator=candidate;}
function finishRecord(){if(recording.value&&candidate){releaseRecording();recording.value=false;recordMessage.value='已录制新组合键，正在自动应用；注册冲突会保留原设置。';candidate='';autosave.request();}}
onMounted(()=>{void load();window.addEventListener('blur',cancelRecord);});
onBeforeUnmount(()=>{alive=false;loadTicket++;cancelRecord();void autosave.flush().finally(()=>editor.dispose());motion?.revert();window.removeEventListener('blur',cancelRecord);});
</script>
<style scoped>
.client-settings{padding:8px 4px 0;max-width:850px;margin:auto}.client-settings header{display:flex;justify-content:space-between;align-items:start;gap:16px}.client-settings header small{font-size:10px;letter-spacing:2px;color:var(--sr-color-text-muted)}h1{font-size:28px;margin:7px 0}.client-settings p{font-size:12px;line-height:1.8;color:var(--sr-color-text-muted)}.client-settings button{min-height:38px;padding:8px 13px;color:inherit;border:1px solid var(--sr-color-line);border-radius:11px;background:var(--sr-color-surface-raised);cursor:pointer}.client-settings button:disabled{opacity:.5;cursor:default}.tabs{display:flex;gap:8px;margin:22px 0}.tabs [aria-selected=true]{background:#d8e6ad;color:#20311e}fieldset{border:0;margin:0;padding:0;min-width:0}.preview{position:relative;border:1px solid var(--sr-color-line);border-radius:18px;background:radial-gradient(ellipse at 35% 120%,#91b9a430,transparent 75%),#13242070;padding:40px 18px 24px;text-align:center;overflow:hidden}.preview small{position:absolute;top:13px;left:17px;font-size:10px;color:var(--sr-color-text-muted)}.sample{font-size:min(var(--lyric-size),6vw);font-weight:700;color:var(--lyric-base);background:linear-gradient(90deg,var(--lyric-highlight) 58%,var(--lyric-base) 58%);background-clip:text;-webkit-text-fill-color:transparent;opacity:var(--lyric-opacity)}.sample-next{color:var(--lyric-base);opacity:var(--lyric-opacity);font-size:15px;margin-top:4px}.row{display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:65px;font-size:13px}.row small{display:block;font-size:11px;color:var(--sr-color-text-muted);margin-top:4px}input[type=checkbox]{appearance:none;width:38px;height:23px;border-radius:20px;background:#b9c8b338;position:relative;flex-shrink:0;cursor:pointer}input[type=checkbox]:before{content:'';position:absolute;top:3px;left:3px;width:17px;height:17px;border-radius:50%;background:#b9c8b3;transition:transform .15s}input[type=checkbox]:checked{background:#d8e6ad}input[type=checkbox]:checked:before{transform:translateX(15px);background:#293d29}.group{padding:20px 0;border-top:1px solid var(--sr-color-line);border-bottom:1px solid var(--sr-color-line);margin:12px 0}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.two label,.group>label{display:block;font-size:12px}.two :deep(.sr-select){display:block;width:100%;margin-top:10px}.slider{display:grid!important;grid-template-columns:1fr auto;font-size:12px;gap:12px;margin:24px 0}.slider input{grid-column:1/-1;width:100%;accent-color:#d8e6ad}.slider output{font-size:11px;color:#d8e6ad}.record{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:70px!important;margin-top:12px;background:#10221c80!important}.record kbd{display:inline-block;border:1px solid #b4c7ac33;border-radius:7px;padding:7px 12px;margin-right:7px;background:#2f4039;box-shadow:0 3px 0 #0a1512}.record small{font-size:11px;color:var(--sr-color-text-muted)}.record.is-recording{outline:2px solid #d8e6ad;outline-offset:3px}.slots{margin:22px 0}.settings-footer{position:sticky;bottom:0;background:#1a2826f5;backdrop-filter:blur(20px);border-top:1px solid var(--sr-color-line);padding:15px 4px;display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:24px;z-index:2;font-size:11px}.settings-footer button{background:#d8e6ad;color:#20311e}.error{color:#f2baa7!important}input:focus-visible,button:focus-visible{outline:2px solid #d8e6ad;outline-offset:3px}@media(max-width:600px){.two{grid-template-columns:1fr}.client-settings header{flex-wrap:wrap}.settings-footer{flex-wrap:wrap}.record{flex-wrap:wrap;gap:14px}}
</style>

<style scoped>
.client-settings{display:block;max-width:850px;padding:0;background:transparent;border:0;border-radius:0;overflow:visible;min-height:0}.settings-nav{padding:0;background:transparent;border:0}.settings-nav .tabs{display:flex;flex-direction:row;margin:0 0 26px;gap:8px;border-bottom:1px solid var(--sr-color-line);padding-bottom:12px}.settings-nav .tabs button{padding:10px 18px}.settings-main{padding:0;min-width:0;overflow:visible;max-height:none}.client-settings h1{font-size:26px}.preview{margin-top:24px}.settings-footer{position:static;background:transparent;backdrop-filter:none;margin-top:20px;padding:15px 0;border-radius:0}@media(max-width:640px){.settings-nav .tabs{flex-wrap:wrap}.settings-main{padding:0;max-height:none}}
</style>
